if __name__ == '__main__':
    for rid, f in ch.items():
        for k, v in f.items(): assert '\n' not in v, (rid, k)
    records.apply(SITE + 'sources.txt', ch)
    # quotes: regularise the English fields of every record (what, note, trans), not passage
    text = open(SITE + 'sources.txt', encoding='utf-8').read()
    recs = records.parse(text); assert records.serialize(recs) == text
    n = 0
    for fields in recs:
        for fl in fields:
            if fl[0] in ('what', 'note', 'trans', 'title'):
                s = smart(fl[1])
                if s != fl[1]: fl[1] = s; n += 1
    open(SITE + 'sources.txt', 'w', encoding='utf-8').write(records.serialize(recs))
    print('quotes regularised in', n, 'fields')
    json.dump(ch, open('/tmp/claude-0/-home-user/47b143d1-a9ed-5a02-adf0-c9c713677b02/scratchpad/debate/final/C2.json', 'w'), ensure_ascii=False, indent=1)
